/**
 * 273 [BK1], files part 1: the exact JSON the backup Worker reads from the
 * site's listing route (app/api/backup/files/route.ts), and the strict
 * parsers it reuses (docs/backup-costs-2026-11-08.md, section 5.1, C4-38).
 *
 * The Worker lives in a separate Cloudflare account that holds no production
 * credential: it calls the route with the route's own secret, gets a page of
 * a store's objects with a read URL for each that lasts minutes, and
 * downloads straight from the origin, so the bytes never pass through Vercel.
 *
 * A files page:
 *
 *   { version: 1, kind: "files", source, store, entries, cursor, complete, reason }
 *   entries: [{ source, key, etag, size, url, expiresAt }]   at most 1,000, 1 MB in all
 *
 * `complete` is true only when the provider said there is nothing after this
 * page (reason "done", no cursor). Otherwise the page is incomplete: "more"
 * (the provider has another page), "cutoff" (the route's time ran out),
 * "page_bytes" (the 1 MB cap), each with a cursor to go on from; or
 * "over_bound" (the store holds more than its pages can list, so its listing
 * can never complete, and no cursor). An incomplete page never holds a
 * deletion: deletion records come on their own page (kind "deletions"), from
 * the records the site keeps, never from what a listing misses.
 *
 * Rule 24: anything else (an extra or missing field, a wrong type, an entry
 * of another source or folder) throws BackupFilesContractError. Unknown is
 * never an empty or complete page.
 */

export const BACKUP_FILES_CONTRACT_VERSION = 1;

/** The sources a store's files are kept in: production R2 (lib/vault.ts), Vercel Blob (lib/blob.ts), Bunny Stream (lib/stream.ts). */
export const BACKUP_FILES_SOURCES = ["r2", "blob", "bunny"] as const;
export type BackupFilesSource = (typeof BACKUP_FILES_SOURCES)[number];

/** Entries a page holds at the most: the providers' own page (Blob `list`, R2 ListObjectsV2 max-keys). */
export const BACKUP_FILES_PAGE_ENTRIES = 1000;
/** Bytes a page's JSON may weigh at the most. */
export const BACKUP_FILES_PAGE_BYTES = 1_000_000;
/** Provider pages one complete listing of one source of one store may take (section 5b: 10 pages a day a source a store). */
export const BACKUP_FILES_PAGES_PER_STORE = 10;
/**
 * Objects one store may hold in one source and still be listed complete
 * (item 8): its pages times their entries. A store past it is answered
 * "over_bound", never complete, so the Worker alarms and applies no orphan end.
 */
export const BACKUP_FILES_HELD_OBJECTS = BACKUP_FILES_PAGES_PER_STORE * BACKUP_FILES_PAGE_ENTRIES;
/**
 * Objects the Worker may copy for one store in a month, all sources together:
 * the 10,000 its R2 operations are priced at (section 5b). The Worker's own
 * ceiling before each copy (past it the copy falls behind and alarms, nothing
 * is claimed copied); never more than one complete listing holds.
 */
export const BACKUP_FILES_OBJECTS_PER_MONTH = 10_000;
/** How long a signed read URL lasts: 15 minutes (R2 allows 1 s to 7 days, Blob at most 7 days). */
export const BACKUP_FILES_URL_SECONDS = 900;

export const BACKUP_FILES_REASONS = ["done", "more", "cutoff", "page_bytes", "over_bound"] as const;
export type BackupFilesReason = (typeof BACKUP_FILES_REASONS)[number];
export const BACKUP_DELETION_REASONS = ["creator_deleted", "store_closed", "privacy_request"] as const;
export type BackupDeletionReason = (typeof BACKUP_DELETION_REASONS)[number];

export type BackupFilesEntry = { source: BackupFilesSource; key: string; etag: string; size: number; url: string; expiresAt: number };
export type BackupFilesPage = {
  version: 1;
  kind: "files";
  source: BackupFilesSource;
  store: string;
  entries: BackupFilesEntry[];
  cursor: string | null;
  complete: boolean;
  reason: BackupFilesReason;
};
export type BackupDeletionRecord = { source: BackupFilesSource; key: string; recordedAt: number; reason: BackupDeletionReason };
export type BackupDeletionPage = {
  version: 1;
  kind: "deletions";
  records: BackupDeletionRecord[];
  cursor: string | null;
  complete: boolean;
  reason: "done" | "more" | "cutoff";
};

export class BackupFilesContractError extends Error {
  constructor(message: string) {
    super(`backup files contract: ${message}`);
    this.name = "BackupFilesContractError";
  }
}

const STORE_PATTERN = /^[0-9a-f]{32}$/;
const CURSOR_PATTERN = /^[A-Za-z0-9_-]{1,4096}$/;
/** An ETag as the providers send it: printable, no spaces; R2's and Blob's come with or without quotes. */
const ETAG_PATTERN = /^[\x21-\x7e]{1,256}$/;
const CONTROL = /[\u0000-\u001f\u007f]/;

/** The folder a store's objects are kept under in a source; null for one whose listing is not built (bunny). */
export function sourcePrefix(source: BackupFilesSource, store: string): string | null {
  if (source === "r2") return `vault/${store}/`;
  if (source === "blob") return `stores/${store}/`;
  return null;
}

const fail = (message: string): never => {
  throw new BackupFilesContractError(message);
};

function exactObject(raw: unknown, fields: readonly string[], what: string): Record<string, unknown> {
  if (!raw || typeof raw !== "object" || Array.isArray(raw) || Object.getPrototypeOf(raw) !== Object.prototype) fail(`${what} is not an object`);
  const value = raw as Record<string, unknown>;
  const own = Object.keys(value);
  if (own.length !== fields.length || !fields.every((field) => Object.hasOwn(value, field))) fail(`${what} has fields ${own.join(",")}, not ${fields.join(",")}`);
  for (const field of fields) {
    const descriptor = Object.getOwnPropertyDescriptor(value, field);
    if (!descriptor || !("value" in descriptor)) fail(`${what}.${field} is not a plain value`);
  }
  return value;
}

const wholeTime = (value: unknown, what: string): number =>
  typeof value === "number" && Number.isSafeInteger(value) && value > 0 ? value : fail(`${what} is not a positive whole time in ms`);

function keyOf(value: unknown, what: string): string {
  if (typeof value !== "string" || value.length < 1 || value.length > 1024 || CONTROL.test(value)) fail(`${what} is not an object key`);
  return value as string;
}

function textOf(raw: unknown): unknown {
  if (typeof raw !== "string") return raw;
  try {
    return JSON.parse(raw) as unknown;
  } catch {
    return fail("the answer is not JSON");
  }
}

function sizeCheck(value: unknown): void {
  if (Buffer.byteLength(JSON.stringify(value), "utf8") > BACKUP_FILES_PAGE_BYTES) fail("the page weighs more than 1 MB");
}

function pageEnd(value: Record<string, unknown>, reasons: readonly string[]): { cursor: string | null; complete: boolean; reason: string } {
  const { cursor, complete, reason } = value;
  if (typeof complete !== "boolean") fail("complete is not a boolean");
  if (typeof reason !== "string" || !reasons.includes(reason)) fail("reason is not one the contract knows");
  if (cursor !== null && (typeof cursor !== "string" || !CURSOR_PATTERN.test(cursor))) fail("cursor is neither null nor base64url");
  if (complete !== (reason === "done")) fail("complete is true exactly when the reason is done");
  if (reason === "done" || reason === "over_bound") {
    if (cursor !== null) fail(`a ${reason as string} page carries no cursor`);
  } else if (cursor === null) fail("an incomplete page needs a cursor to go on from");
  return { cursor: cursor as string | null, complete: complete as boolean, reason: reason as string };
}

const PAGE_FIELDS = ["version", "kind", "source", "store", "entries", "cursor", "complete", "reason"] as const;
const ENTRY_FIELDS = ["source", "key", "etag", "size", "url", "expiresAt"] as const;

/** A files page, exactly, from its JSON text or its parsed value; throws BackupFilesContractError on anything else. */
export function parseFilesPage(raw: unknown): BackupFilesPage {
  const parsed = textOf(raw);
  const value = exactObject(parsed, PAGE_FIELDS, "page");
  if (value.version !== BACKUP_FILES_CONTRACT_VERSION) fail("version is not 1");
  if (value.kind !== "files") fail("kind is not files");
  const source = value.source;
  if (typeof source !== "string" || !(BACKUP_FILES_SOURCES as readonly string[]).includes(source)) fail("source is not one the contract knows");
  const store = value.store;
  if (typeof store !== "string" || !STORE_PATTERN.test(store)) fail("store is not a folder");
  const prefix = sourcePrefix(source as BackupFilesSource, store as string);
  if (prefix === null) fail(`no listing of ${source as string} is built`);
  if (!Array.isArray(value.entries)) fail("entries is not a list");
  const list = value.entries as unknown[];
  if (list.length > BACKUP_FILES_PAGE_ENTRIES) fail("more than 1,000 entries");
  sizeCheck(parsed);
  const seen = new Set<string>();
  const entries: BackupFilesEntry[] = list.map((item, i) => {
    const entry = exactObject(item, ENTRY_FIELDS, `entries[${i}]`);
    if (entry.source !== source) fail(`entries[${i}] is of another source`);
    const key = keyOf(entry.key, `entries[${i}].key`);
    if (!key.startsWith(prefix as string) || key.length === (prefix as string).length) fail(`entries[${i}].key is outside the store's folder`);
    if (seen.has(key)) fail(`entries[${i}].key is listed twice`);
    seen.add(key);
    if (typeof entry.etag !== "string" || !ETAG_PATTERN.test(entry.etag)) fail(`entries[${i}].etag is not an etag`);
    if (typeof entry.size !== "number" || !Number.isSafeInteger(entry.size) || entry.size < 0) fail(`entries[${i}].size is not a count of bytes`);
    let url: URL | null = null;
    try {
      url = typeof entry.url === "string" && entry.url.length <= 8192 ? new URL(entry.url) : null;
    } catch {
      url = null;
    }
    if (!url || url.protocol !== "https:" || url.username || url.password) fail(`entries[${i}].url is not a plain https URL`);
    return { source: source as BackupFilesSource, key, etag: entry.etag as string, size: entry.size as number, url: entry.url as string, expiresAt: wholeTime(entry.expiresAt, `entries[${i}].expiresAt`) };
  });
  const end = pageEnd(value, BACKUP_FILES_REASONS);
  return { version: 1, kind: "files", source: source as BackupFilesSource, store: store as string, entries, cursor: end.cursor, complete: end.complete, reason: end.reason as BackupFilesReason };
}

const DELETION_FIELDS = ["version", "kind", "records", "cursor", "complete", "reason"] as const;
const RECORD_FIELDS = ["source", "key", "recordedAt", "reason"] as const;

/** A page of deletion records, exactly; throws BackupFilesContractError on anything else. Nothing about the person is in a record. */
export function parseDeletionPage(raw: unknown): BackupDeletionPage {
  const parsed = textOf(raw);
  const value = exactObject(parsed, DELETION_FIELDS, "deletion page");
  if (value.version !== BACKUP_FILES_CONTRACT_VERSION) fail("version is not 1");
  if (value.kind !== "deletions") fail("kind is not deletions");
  if (!Array.isArray(value.records)) fail("records is not a list");
  const list = value.records as unknown[];
  if (list.length > BACKUP_FILES_PAGE_ENTRIES) fail("more than 1,000 records");
  sizeCheck(parsed);
  const records: BackupDeletionRecord[] = list.map((item, i) => {
    const record = exactObject(item, RECORD_FIELDS, `records[${i}]`);
    if (typeof record.source !== "string" || !(BACKUP_FILES_SOURCES as readonly string[]).includes(record.source)) fail(`records[${i}].source is not one the contract knows`);
    if (typeof record.reason !== "string" || !(BACKUP_DELETION_REASONS as readonly string[]).includes(record.reason)) fail(`records[${i}].reason is not one the contract knows`);
    return { source: record.source as BackupFilesSource, key: keyOf(record.key, `records[${i}].key`), recordedAt: wholeTime(record.recordedAt, `records[${i}].recordedAt`), reason: record.reason as BackupDeletionReason };
  });
  const end = pageEnd(value, ["done", "more", "cutoff"]);
  return { version: 1, kind: "deletions", records, cursor: end.cursor, complete: end.complete, reason: end.reason as BackupDeletionPage["reason"] };
}

lib/backup-files-source.ts:
/**
 * 273 [BK1], files part 1: what the backup files route does
 * (app/api/backup/files/route.ts): it lists one source of one store a page
 * at a time and signs a short-lived read URL for each object it lists.
 * Nothing else. It never reads, writes or deletes a file's bytes, so the bytes
 * go from the origin straight to the backup Worker, never through Vercel
 * (docs/backup-costs-2026-11-08.md, section 5.1; C1-20261108-2031-C4-38).
 *
 * Off, each checked before any provider is asked or any command is sent:
 *   - no route secret (BACKUP_FILES_ROUTE_SECRET, at least 32 characters, and
 *     never the same as another secret of the site): 404;
 *   - no review of the route's cost (lib/backup-files-review.ts, null until
 *     the owner approves it): 404, even with the secret;
 *   - a source whose provider details are not confirmed: R2 (whether its
 *     listing carries each object's ETag, lib/backup-files-r2.ts) and Bunny
 *     Stream (which token method the pull zone uses, its host, whether a
 *     video's original is kept, and what stands for a video's etag): 503
 *     "source_off". Only Vercel Blob is listed today.
 *
 * Who holds what: the Worker holds the route's secret and nothing else of
 * production. A stolen secret lists names and reads files for minutes; it can
 * never write or delete, because the route only lists and signs `get`.
 *
 * Vercel Blob (vercel-signed-urls page, `last_updated: 2026-09-15`, reread
 * 2026-11-08 22:55 UTC): ONE `issueSignedToken({ operations: ["get"],
 * pathname: "*", validUntil })` a call, made only when there is something to
 * sign, then `presignUrl` for each object, which is HMAC-only (no network
 * call). The token's clientSigningToken never leaves this file.
 *
 * Bounds:
 *   - at most BACKUP_FILES_PAGE_ENTRIES entries and BACKUP_FILES_PAGE_BYTES a
 *     page; signing stops at the internal cutoff (BACKUP_FILES_CUTOFF_MS) and
 *     the page so far is answered incomplete with a cursor that resumes after
 *     the last entry signed, losing none;
 *   - at most BACKUP_FILES_PAGES_PER_STORE provider pages a listing: a store
 *     with more objects is answered "over_bound", never complete (item 8);
 *   - at most the review's maxPagesPerDay pages a UTC day for each source,
 *     counted before the provider is asked (one SET NX EX and one INCRBY, read
 *     in their exact shape, rule 24): past it 429, unreadable 503.
 *
 *   nl:backup:files:day:<YYYY-MM-DD>:<source>   the day's pages of one source, kept two days
 *
 * Rule 24: a listing or a token that cannot be read in its exact shape throws,
 * and the route answers 503: never an empty or complete page.
 */
import { createHash, timingSafeEqual } from "node:crypto";
import * as blob from "@/lib/blob";
import {
  BACKUP_FILES_PAGE_BYTES,
  BACKUP_FILES_PAGE_ENTRIES,
  BACKUP_FILES_PAGES_PER_STORE,
  BACKUP_FILES_URL_SECONDS,
  type BackupFilesEntry,
  type BackupFilesPage,
  type BackupFilesReason,
  type BackupFilesSource,
  parseFilesPage,
  sourcePrefix,
} from "@/lib/backup-files-contract";
import { backupFilesR2Config, listR2Page, presignR2Get } from "@/lib/backup-files-r2";
import type { BackupFilesRouteReview } from "@/lib/backup-files-review";
import { redisPipeline } from "@/lib/redis";

/** The shortest route secret taken as set. */
export const BACKUP_FILES_SECRET_MIN = 32;
/** When signing stops inside a call, from its start: the rest goes on the next page. */
export const BACKUP_FILES_CUTOFF_MS = 8_000;
/** The hard end of a call, from its start, for every request inside it (lib/fetch-timeout.ts withCutoff), inside the route's 10 s. */
export const BACKUP_FILES_REQUEST_MS = 9_000;

/** Why a source is not listed, or null when it is. Changing one needs its provider detail confirmed from an official page first. */
const SOURCE_OFF: Record<BackupFilesSource, string | null> = {
  blob: null,
  r2: "r2_listing_etag_unconfirmed",
  bunny: "bunny_signing_unconfirmed",
};

export function backupFilesSourceOff(source: BackupFilesSource): string | null {
  return SOURCE_OFF[source];
}

/** Settings the route's secret may never equal: one secret stolen must never be another. */
const OTHER_SECRETS = [
  "CRON_SECRET",
  "BLOB_READ_WRITE_TOKEN",
  "R2_ACCESS_KEY_ID",
  "R2_SECRET_ACCESS_KEY",
  "BACKUP_FILES_R2_READ_SECRET",
  "BUNNY_STREAM_API_KEY",
  "BUNNY_STREAM_TOKEN_KEY",
  "BUNNY_STREAM_READ_KEY",
  "BACKUP_ENCRYPTION_KEY",
];

/** The route's own secret, or null when it is unset, short, or the same as another secret of the site. */
export function backupFilesRouteSecret(env: Record<string, string | undefined> = process.env): string | null {
  const secret = (env.BACKUP_FILES_ROUTE_SECRET ?? "").trim();
  if (secret.length < BACKUP_FILES_SECRET_MIN) return null;
  if (OTHER_SECRETS.some((name) => (env[name] ?? "").trim() === secret)) return null;
  return secret;
}

const digest = (text: string) => createHash("sha256").update(text, "utf8").digest();

/** Whether an Authorization header is exactly "Bearer <secret>", compared in constant time. */
export function secretMatches(header: string | null, secret: string): boolean {
  const given = typeof header === "string" && header.startsWith("Bearer ") ? header.slice("Bearer ".length) : "";
  // Both sides hashed first: equal lengths, so the comparison takes the same time whatever was sent.
  return timingSafeEqual(digest(given), digest(secret)) && given.length > 0;
}

/** The review read once from its own data fields (never a getter), or null: no review, the route stays off. */
export function admitFilesReview(raw: unknown): BackupFilesRouteReview | null {
  if (!raw || typeof raw !== "object" || Object.getPrototypeOf(raw) !== Object.prototype) return null;
  const read = (name: string): unknown => {
    const descriptor = Object.getOwnPropertyDescriptor(raw, name);
    return descriptor && "value" in descriptor ? descriptor.value : undefined;
  };
  const maxPagesPerDay = read("maxPagesPerDay");
  const reviewedAt = read("reviewedAt");
  const source = read("source");
  if (typeof maxPagesPerDay !== "number" || !Number.isSafeInteger(maxPagesPerDay) || maxPagesPerDay < 1 || maxPagesPerDay > 1_000_000) return null;
  if (typeof reviewedAt !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(reviewedAt) || typeof source !== "string" || source.trim().length < 3) return null;
  return { maxPagesPerDay, reviewedAt, source };
}

// -------------------------------------------------------------------- cursor

type CursorState = { page: number; provider: string | null; after: string | null };

/** Where the next page starts: the provider page (its index and its own cursor) and the last key signed in it, if any. */
export function encodeFilesCursor(source: BackupFilesSource, store: string, state: CursorState): string {
  return Buffer.from(JSON.stringify({ v: 1, s: source, st: store, p: state.page, c: state.provider, a: state.after }), "utf8").toString("base64url");
}

const CONTROL = /[\u0000-\u001f\u007f]/;

/** A cursor this route made for this source and store, or null for anything else. */
export function decodeFilesCursor(text: string, source: BackupFilesSource, store: string): CursorState | null {
  if (!/^[A-Za-z0-9_-]{1,4096}$/.test(text)) return null;
  let value: unknown;
  try {
    value = JSON.parse(Buffer.from(text, "base64url").toString("utf8"));
  } catch {
    return null;
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const { v, s, st, p, c, a, ...rest } = value as Record<string, unknown>;
  if (Object.keys(rest).length || v !== 1 || s !== source || st !== store) return null;
  if (typeof p !== "number" || !Number.isSafeInteger(p) || p < 0 || p >= BACKUP_FILES_PAGES_PER_STORE) return null;
  const text1 = (x: unknown, most: number) => x === null || (typeof x === "string" && x.length > 0 && x.length <= most && !CONTROL.test(x));
  if (!text1(c, 2048) || !text1(a, 1024)) return null;
  if (p > 0 && c === null) return null;
  return { page: p, provider: c as string | null, after: a as string | null };
}

// ------------------------------------------------------------- day's ceiling

/** Takes one of the day's reviewed pages for a source before the provider is asked: "ok", "over" past it, "unknown" when the count cannot be read. */
export async function takeDayPage(source: BackupFilesSource, review: BackupFilesRouteReview, now = Date.now()): Promise<"ok" | "over" | "unknown"> {
  const key = `nl:backup:files:day:${new Date(now).toISOString().slice(0, 10)}:${source}`;
  try {
    // Exactly two replies: the SET's "OK" or null, and the INCRBY's own integer. Anything else is unknown (rule 24).
    const reply: unknown = await redisPipeline([["SET", key, "0", "NX", "EX", 2 * 86_400], ["INCRBY", key, 1]]);
    const count = Array.isArray(reply) && reply.length === 2 && (reply[0] === null || reply[0] === "OK") ? reply[1] : undefined;
    if (typeof count !== "number" || !Number.isSafeInteger(count) || count < 1) return "unknown";
    return count > review.maxPagesPerDay ? "over" : "ok";
  } catch {
    return "unknown";
  }
}

// ------------------------------------------------------------------- listing

type Listed = { objects: { key: string; etag: string; size: number }[]; next: string | null };

class SourceError extends Error {
  constructor(message: string) {
    super(`backup files source: ${message}`);
    this.name = "BackupFilesSourceError";
  }
}
const fail = (message: string): never => {
  throw new SourceError(message);
};

/** One page of Vercel Blob under `prefix`, read in its exact shape; throws on anything else. */
async function listBlob(prefix: string, cursor: string | null): Promise<Listed> {
  const answer: unknown = await blob.list({ prefix, limit: BACKUP_FILES_PAGE_ENTRIES, cursor: cursor ?? undefined });
  if (!answer || typeof answer !== "object") fail("the listing is not an object");
  const { blobs, hasMore, cursor: next } = answer as { blobs?: unknown; hasMore?: unknown; cursor?: unknown };
  if (!Array.isArray(blobs) || blobs.length > BACKUP_FILES_PAGE_ENTRIES || typeof hasMore !== "boolean") fail("the listing has no list of at most 1,000 or no hasMore");
  if (hasMore && (typeof next !== "string" || next.length === 0 || next.length > 2048)) fail("more is said to follow, with no cursor");
  const seen = new Set<string>();
  const objects = (blobs as unknown[]).map((item) => {
    const { pathname, size, etag } = (item ?? {}) as { pathname?: unknown; size?: unknown; etag?: unknown };
    if (typeof pathname !== "string" || !pathname.startsWith(prefix) || pathname.length === prefix.length || pathname.length > 1024 || seen.has(pathname)) fail("an entry outside the folder, or twice");
    seen.add(pathname as string);
    if (typeof size !== "number" || !Number.isSafeInteger(size) || size < 0) fail("a size that is not a count");
    if (typeof etag !== "string" || !/^[\x21-\x7e]{1,256}$/.test(etag)) fail("an entry without its etag");
    return { key: pathname as string, etag: etag as string, size: size as number };
  });
  return { objects, next: hasMore ? (next as string) : null };
}

type Signer = (key: string) => Promise<{ url: string; expiresAt: number }>;

/** Blob's signer: one get-only token for "*" made on the first object to sign, then a local signature each. */
function blobSigner(now: () => number): Signer {
  let token: { delegationToken: string; clientSigningToken: string; validUntil: number } | null = null;
  return async (key) => {
    if (!token) {
      const asked = now() + BACKUP_FILES_URL_SECONDS * 1000;
      const issued: unknown = await blob.issueSignedToken({ operations: ["get"], pathname: "*", validUntil: asked });
      const { delegationToken, clientSigningToken, validUntil } = (issued ?? {}) as Record<string, unknown>;
      if (typeof delegationToken !== "string" || !delegationToken || typeof clientSigningToken !== "string" || !clientSigningToken) fail("a token without its parts");
      if (typeof validUntil !== "number" || !Number.isSafeInteger(validUntil) || validUntil < now() + 60_000) fail("a token that runs out within a minute");
      token = { delegationToken: delegationToken as string, clientSigningToken: clientSigningToken as string, validUntil: Math.min(validUntil as number, asked) };
    }
    const held = token;
    const signed: unknown = await blob.presignUrl({ delegationToken: held.delegationToken, clientSigningToken: held.clientSigningToken }, { operation: "get", pathname: key, access: "private", validUntil: held.validUntil });
    const url = (signed as { presignedUrl?: unknown } | null)?.presignedUrl;
    if (typeof url !== "string" || !url.startsWith("https://") || url.includes(held.clientSigningToken)) fail("a signed URL it cannot hand out");
    return { url: url as string, expiresAt: held.validUntil };
  };
}

function sourceOf(source: BackupFilesSource, now: () => number): { list: (prefix: string, cursor: string | null) => Promise<Listed>; sign: Signer } {
  const off = SOURCE_OFF[source];
  if (off) fail(`${source} is off (${off})`);
  if (source === "blob") return { list: listBlob, sign: blobSigner(now) };
  const config = backupFilesR2Config();
  if (source !== "r2" || !config) return fail(`${source} is not set up`);
  return {
    list: (prefix, cursor) => listR2Page(config, prefix, cursor),
    sign: async (key) => {
      const at = now();
      return { url: presignR2Get(config, key, BACKUP_FILES_URL_SECONDS, new Date(at)), expiresAt: Math.floor(at / 1000) * 1000 + BACKUP_FILES_URL_SECONDS * 1000 };
    },
  };
}

/** Room kept in a page's 1 MB for its own fields and its cursor. */
const PAGE_HEAD_BYTES = 8_192;

/**
 * One page of one source of one store, from `cursor` (null for the first):
 * at most one provider page, its objects signed until the cutoff or the
 * page's bytes run out. Throws when the provider cannot be read in its exact
 * shape; the page it returns has passed parseFilesPage.
 */
export async function backupFilesPage(
  input: { source: BackupFilesSource; store: string; cursor: string | null },
  options: { stopAt: number; now?: () => number },
): Promise<BackupFilesPage> {
  const now = options.now ?? Date.now;
  const prefix = sourcePrefix(input.source, input.store);
  if (prefix === null) return fail(`no listing of ${input.source} is built`);
  const state = input.cursor === null ? { page: 0, provider: null, after: null } : decodeFilesCursor(input.cursor, input.source, input.store);
  if (!state) return fail("a cursor this route did not make");
  const source = sourceOf(input.source, now);
  const answer = (entries: BackupFilesEntry[], reason: BackupFilesReason, next: CursorState | null) =>
    parseFilesPage({
      version: 1,
      kind: "files",
      source: input.source,
      store: input.store,
      entries,
      cursor: next ? encodeFilesCursor(input.source, input.store, next) : null,
      complete: reason === "done",
      reason,
    });

  if (now() >= options.stopAt) return answer([], "cutoff", state);
  const listed = await source.list(prefix, state.provider);
  let objects = listed.objects;
  if (state.after !== null) {
    // Resume after the last entry signed. If the provider page changed and it is gone, the whole page again:
    // an entry twice is harmless to the Worker (same key and etag), one lost is not.
    const at = objects.findIndex((object) => object.key === state.after);
    if (at >= 0) objects = objects.slice(at + 1);
  }
  const entries: BackupFilesEntry[] = [];
  let bytes = PAGE_HEAD_BYTES;
  for (const object of objects) {
    const resume = { page: state.page, provider: state.provider, after: entries.length ? entries[entries.length - 1].key : state.after };
    if (now() >= options.stopAt) return answer(entries, "cutoff", resume);
    const signed = await source.sign(object.key);
    const entry: BackupFilesEntry = { source: input.source, key: object.key, etag: object.etag, size: object.size, url: signed.url, expiresAt: signed.expiresAt };
    const weight = Buffer.byteLength(JSON.stringify(entry), "utf8") + 1;
    if (bytes + weight > BACKUP_FILES_PAGE_BYTES) return answer(entries, "page_bytes", resume);
    bytes += weight;
    entries.push(entry);
  }
  if (listed.next === null) return answer(entries, "done", null);
  if (state.page + 1 >= BACKUP_FILES_PAGES_PER_STORE) return answer(entries, "over_bound", null);
  return answer(entries, "more", { page: state.page + 1, provider: listed.next, after: null });
}

lib/backup-files-r2.ts:
/**
 * 273 [BK1], files part 1: listing the production R2 bucket and presigning
 * one GET for the backup Worker, with a token of the route's own.
 *
 * The site's own key (R2_ACCESS_KEY_ID / R2_SECRET_ACCESS_KEY, lib/vault.ts)
 * reads and writes. This file never uses it: it signs with an "Object Read
 * only" token scoped to the bucket that the owner creates for the route alone
 * (R2 tokens page, "Last updated Oct 1, 2026", read 2026-11-08), so that even
 * a bug here cannot sign a write or a delete that R2 would accept. A key equal
 * to the site's is refused.
 *
 * Schemes, cited (docs/backup-costs-2026-11-08.md, section 2):
 *   - presigned GET: Signature Version 4 in the query, one operation on one
 *     object, 1 s to 7 days, made locally with no call to R2 (R2 presigned-URL
 *     page, "Last updated Oct 26, 2026", read 2026-11-08); lib/aws-sign.ts
 *     presignV4, held to Amazon's published example and already used for
 *     buyers' downloads (lib/vault.ts vaultUrl);
 *   - listing: S3 ListObjectsV2 (list-type=2, prefix, max-keys, continuation-
 *     token), as lib/vault.ts listVault already asks R2. Each <Contents> must
 *     hold exactly one Key, Size and ETag. That R2's answer carries the ETag
 *     is S3's documented shape, NOT confirmed from an R2 page in this work
 *     (developers.cloudflare.com was unreachable on 2026-11-08): so the route
 *     keeps this source off (lib/backup-files-source.ts), and an entry
 *     without its ETag fails the listing here, never passes as an empty one.
 *
 * Settings, none set by this work: R2_ACCOUNT_ID and R2_BUCKET (the site's),
 * BACKUP_FILES_R2_READ_KEY_ID and BACKUP_FILES_R2_READ_SECRET (the read-only
 * token's, the owner's to create).
 */
import { type AwsKey, EMPTY_HASH, presignV4, signV4 } from "@/lib/aws-sign";
import { VAULT_TIMEOUT_MS, timed } from "@/lib/fetch-timeout";
import { BACKUP_FILES_PAGE_ENTRIES } from "@/lib/backup-files-contract";

export type BackupFilesR2Config = { endpoint: string; bucket: string; key: AwsKey };

type Env = Record<string, string | undefined>;

/** The route's read-only R2 settings; null when any is missing or the key is the site's own read-write key. */
export function backupFilesR2Config(env: Env = process.env): BackupFilesR2Config | null {
  const account = (env.R2_ACCOUNT_ID ?? "").trim();
  const bucket = (env.R2_BUCKET ?? "").trim();
  const accessKeyId = (env.BACKUP_FILES_R2_READ_KEY_ID ?? "").trim();
  const secretAccessKey = (env.BACKUP_FILES_R2_READ_SECRET ?? "").trim();
  if (!/^[0-9a-f]{32}$/.test(account) || !/^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$/.test(bucket)) return null;
  if (accessKeyId.length < 16 || secretAccessKey.length < 32) return null;
  if (accessKeyId === (env.R2_ACCESS_KEY_ID ?? "").trim() || secretAccessKey === (env.R2_SECRET_ACCESS_KEY ?? "").trim()) return null;
  return { endpoint: `https://${account}.r2.cloudflarestorage.com`, bucket, key: { accessKeyId, secretAccessKey } };
}

/** A presigned GET of one object for `seconds`, made here with no call to R2. */
export function presignR2Get(config: BackupFilesR2Config, key: string, seconds: number, now: Date = new Date()): string {
  return presignV4({ method: "GET", url: `${config.endpoint}/${config.bucket}/${key}`, expires: seconds, region: "auto", service: "s3", key: config.key, now });
}

export class R2ListingError extends Error {
  constructor(message: string) {
    super(`R2 listing: ${message}`);
    this.name = "R2ListingError";
  }
}
const fail = (message: string): never => {
  throw new R2ListingError(message);
};

const ESCAPES: Record<string, string> = { "&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": '"', "&apos;": "'" };
/** The five XML escapes undone; any other `&` (a numeric reference) is not read. */
function unescape(text: string): string {
  return text.replace(/&[^;]{0,10};|&/g, (found) => ESCAPES[found] ?? fail(`an escape it does not read (${found})`));
}

/** The one value of a tag in an XML fragment, exactly once; anything else fails. */
function once(xml: string, name: string): string {
  const openings = xml.match(new RegExp(`<(?:[A-Za-z_][A-Za-z0-9_.-]*:)?${name}[\\s>/]`, "g")) ?? [];
  const values = [...xml.matchAll(new RegExp(`<${name}>([^<]*)</${name}>`, "g"))];
  if (openings.length !== 1 || values.length !== 1) fail(`${name} is not there exactly once`);
  return unescape(values[0][1]);
}

/** One page of the bucket under `prefix`: each object's key, etag and size, and the token to go on from. Throws on anything not exact (rule 24). */
export async function listR2Page(config: BackupFilesR2Config, prefix: string, cursor: string | null): Promise<{ objects: { key: string; etag: string; size: number }[]; next: string | null }> {
  const url = new URL(`${config.endpoint}/${config.bucket}`);
  url.searchParams.set("list-type", "2");
  url.searchParams.set("prefix", prefix);
  url.searchParams.set("max-keys", String(BACKUP_FILES_PAGE_ENTRIES));
  if (cursor) url.searchParams.set("continuation-token", cursor);
  const headers = signV4({ method: "GET", url: url.toString(), headers: { "x-amz-content-sha256": EMPTY_HASH }, payloadHash: EMPTY_HASH, region: "auto", service: "s3", key: config.key });
  const answer = await timed(VAULT_TIMEOUT_MS, async (signal) => {
    const response = await fetch(url.toString(), { method: "GET", headers: { ...headers, "accept-encoding": "identity" }, signal, cache: "no-store" });
    return { status: response.status, text: await response.text() };
  });
  if (answer.status !== 200) fail(`answered ${answer.status}`);
  const xml = answer.text;
  const opened = xml.indexOf("<ListBucketResult");
  const closed = xml.lastIndexOf("</ListBucketResult>");
  if (opened < 0 || closed < opened || xml.slice(closed + "</ListBucketResult>".length).trim() !== "") fail("not one whole ListBucketResult");
  const truncated = once(xml, "IsTruncated");
  if (truncated !== "true" && truncated !== "false") fail("IsTruncated is not true or false");
  const entries = xml.match(/<Contents>[\s\S]*?<\/Contents>/g) ?? [];
  if ((xml.match(/<(?:[A-Za-z_][A-Za-z0-9_.-]*:)?Contents[\s>/]/g) ?? []).length !== entries.length) fail("a Contents it cannot read");
  if (entries.length > BACKUP_FILES_PAGE_ENTRIES) fail("more than 1,000 entries");
  for (const name of ["KeyCount", "MaxKeys"]) {
    if (!new RegExp(`<${name}[\\s>/]`).test(xml.replace(/<Contents>[\s\S]*?<\/Contents>/g, ""))) continue;
    const count = once(xml.replace(/<Contents>[\s\S]*?<\/Contents>/g, ""), name);
    if (!/^\d{1,7}$/.test(count)) fail(`${name} is not a count`);
    if (name === "KeyCount" ? Number(count) !== entries.length : Number(count) < entries.length) fail(`${name} does not match the entries`);
  }
  const seen = new Set<string>();
  const objects = entries.map((entry) => {
    const key = once(entry, "Key");
    const size = once(entry, "Size");
    const etag = once(entry, "ETag").replace(/^"(.*)"$/, "$1");
    if (!key.startsWith(prefix) || key.length === prefix.length || seen.has(key)) fail("an entry outside the prefix, or twice");
    seen.add(key);
    if (!/^\d{1,15}$/.test(size)) fail("a size that is not a count");
    if (!/^[\x21-\x7e]{1,256}$/.test(etag)) fail("an etag it cannot read");
    return { key, etag, size: Number(size) };
  });
  const next = truncated === "true" ? once(xml.replace(/<Contents>[\s\S]*?<\/Contents>/g, ""), "NextContinuationToken") : null;
  if (truncated === "true" && !next) fail("truncated without its token");
  return { objects, next };
}

lib/blob.ts:
/**
 * Vercel Blob, with a limit on how long we wait (lib/fetch-timeout.ts).
 *
 * The same functions as "@vercel/blob", taking the same arguments, for every
 * server file to import instead of it. Each call is given an abort signal:
 * BLOB_TIMEOUT_MS (15 s) to an answer — for `get`, until the download
 * starts, never cutting the file short once it is flowing to the buyer —
 * and BLOB_WRITE_TIMEOUT_MS (45 s) for `put`, which writes a stamped PDF of
 * up to 50 MB. The SDK tries a failed request again by itself (up to ten
 * times); the limit covers all of its tries together, so a store that keeps
 * failing cannot hold a page for minutes. Given up, a call fails as one that
 * could not reach Blob does, and every caller already handles that: a
 * download says it could not fetch the file, a removal is logged and left.
 *
 * Signing a URL (presignUrl) is worked out here without asking Blob, so it
 * is passed through as it is.
 */
import * as sdk from "@vercel/blob";
import { BLOB_TIMEOUT_MS, BLOB_WRITE_TIMEOUT_MS, timed } from "@/lib/fetch-timeout";

type Options<F extends (...args: never[]) => unknown, I extends number> = NonNullable<Parameters<F>[I]>;

export function get(pathname: string, options: Options<typeof sdk.get, 1>): ReturnType<typeof sdk.get> {
  return timed(BLOB_TIMEOUT_MS, (abortSignal) => sdk.get(pathname, { ...options, abortSignal }));
}

export function head(pathname: string, options: Options<typeof sdk.head, 1> = {}): ReturnType<typeof sdk.head> {
  return timed(BLOB_TIMEOUT_MS, (abortSignal) => sdk.head(pathname, { ...options, abortSignal }));
}

export function del(pathnames: string | string[], options: Options<typeof sdk.del, 1> = {}): ReturnType<typeof sdk.del> {
  return timed(BLOB_TIMEOUT_MS, (abortSignal) => sdk.del(pathnames, { ...options, abortSignal }));
}

export function list(options: Options<typeof sdk.list, 0> = {}): ReturnType<typeof sdk.list> {
  return timed(BLOB_TIMEOUT_MS, (abortSignal) => sdk.list({ ...options, abortSignal }));
}

export function put(
  pathname: string,
  body: Parameters<typeof sdk.put>[1],
  options: Options<typeof sdk.put, 2>,
): ReturnType<typeof sdk.put> {
  return timed(BLOB_WRITE_TIMEOUT_MS, (abortSignal) => sdk.put(pathname, body, { ...options, abortSignal }));
}

export function issueSignedToken(options: Options<typeof sdk.issueSignedToken, 0>): ReturnType<typeof sdk.issueSignedToken> {
  return timed(BLOB_TIMEOUT_MS, (abortSignal) => sdk.issueSignedToken({ ...options, abortSignal }));
}

export const presignUrl: typeof sdk.presignUrl = (...args) => sdk.presignUrl(...args);

tests/backup-files-route.test.ts:
/**
 * 273 [BK1], files part 1: the route the backup Worker calls to list a
 * store's files and get short-lived read URLs (app/api/backup/files/route.ts,
 * lib/backup-files-source.ts), against a stand-in Vercel Blob
 * (tests/backup-files-world.ts), the in-memory database and a synthetic
 * review (tests/backup-files-review-fixture.ts). Nothing real is reached.
 *
 * What fails here:
 *   - any answer but 404 while the route's own secret is unset, too short,
 *     the same as another secret of the site, or not the one sent; or any
 *     provider call or database command before the secret is checked;
 *   - a method that could write or delete (only GET is exported);
 *   - more than ONE token call for a page, a token that is not get-only for
 *     "*", or the token's clientSigningToken, the Blob write token or the
 *     route's secret anywhere in an answer;
 *   - an unreadable or malformed listing answered as a page (rule 24): it is
 *     a 503, never an empty, complete page;
 *   - a page past its cutoff or 1 MB answered as complete, or a resume that
 *     loses or repeats an entry;
 *   - a store with more objects than its pages can list called complete;
 *   - a call past the day's reviewed pages, or one whose count could not be
 *     read, that reaches the provider;
 *   - R2 or bunny answered as a listing while their provider details are
 *     unconfirmed, and deletion records answered while none are kept.
 */
import * as route from "@/app/api/backup/files/route";
import { BACKUP_FILES_PAGES_PER_STORE, BACKUP_FILES_URL_SECONDS, parseFilesPage, type BackupFilesPage } from "@/lib/backup-files-contract";
import { backupFilesPage, backupFilesRouteSecret, decodeFilesCursor } from "@/lib/backup-files-source";
import { blobWorld, resetBlobWorld } from "./backup-files-world";
import { store as redis } from "./redis-stub";
import { done, is, part } from "./check";

const STORE = "0123456789abcdef0123456789abcdef";
const OTHER = "fedcba9876543210fedcba9876543210";
const SECRET = "route-secret-synthetic-0123456789abcdef";
const PREFIX = `stores/${STORE}/`;

const blobs = (from: number, count: number, key = (n: number) => `${PREFIX}file-${String(n).padStart(5, "0")}.pdf`) =>
  Array.from({ length: count }, (_, i) => ({ pathname: key(from + i), size: 100 + from + i, etag: `"e${from + i}"`, url: "https://x", downloadUrl: "https://x", uploadedAt: new Date(0) }));
const listing = (items: unknown[], more: string | null = null) => ({ blobs: items, hasMore: more !== null, ...(more !== null ? { cursor: more } : {}) });

let commands: unknown[][] = [];
const realPipeline = redis.pipeline.bind(redis);
redis.pipeline = (async (list: unknown[][]) => {
  commands.push(...list);
  return realPipeline(list as (string | number)[][]);
}) as typeof redis.pipeline;

function reset(): void {
  resetBlobWorld();
  commands = [];
  redis.clear();
  process.env.BACKUP_FILES_ROUTE_SECRET = SECRET;
  process.env.CRON_SECRET = "cron-secret-synthetic-0123456789abcdef";
  process.env.BLOB_READ_WRITE_TOKEN = "vercel_blob_rw_synthetic_write_token_0123456789";
}

async function call(query: string, auth: string | null = `Bearer ${SECRET}`, method = "GET"): Promise<{ status: number; text: string; json: unknown }> {
  const headers = new Headers();
  if (auth !== null) headers.set("authorization", auth);
  const response = await route.GET(new Request(`https://marktmorgen.test/api/backup/files${query}`, { method, headers }));
  const text = await response.text();
  let json: unknown = null;
  try { json = JSON.parse(text); } catch { json = null; }
  return { status: response.status, text, json };
}
const nothingReached = () => [blobWorld.listCalls.length, blobWorld.tokenCalls.length, blobWorld.presignCalls.length, commands.length];

async function main(): Promise<void> {
  part("off without its own secret: 404, with no listing and nothing reached");
  reset();
  delete process.env.BACKUP_FILES_ROUTE_SECRET;
  blobWorld.pages = [listing(blobs(0, 3))];
  let answer = await call(`?source=blob&store=${STORE}`);
  is("no secret set", [answer.status, answer.text.includes("stores/")], [404, false]);
  is("nothing listed, signed or counted", nothingReached(), [0, 0, 0, 0]);
  process.env.BACKUP_FILES_ROUTE_SECRET = "short";
  is("a secret under 32 characters counts as unset", (await call(`?source=blob&store=${STORE}`, "Bearer short")).status, 404);
  for (const other of ["CRON_SECRET", "BLOB_READ_WRITE_TOKEN"]) {
    process.env.BACKUP_FILES_ROUTE_SECRET = process.env[other];
    is(`a secret equal to ${other} counts as unset`, [(await call(`?source=blob&store=${STORE}`, `Bearer ${process.env[other]}`)).status, backupFilesRouteSecret()], [404, null]);
  }
  reset();
  blobWorld.pages = [listing(blobs(0, 3))];
  for (const auth of [null, "Bearer wrong-secret-of-the-same-length-000000", `Bearer ${SECRET}x`, SECRET, `Basic ${SECRET}`]) {
    is(`a call with ${auth === null ? "no" : "a wrong"} authorization is a 404`, (await call(`?source=blob&store=${STORE}`, auth)).status, 404);
  }
  is("still nothing listed, signed or counted", nothingReached(), [0, 0, 0, 0]);

  part("only lists and signs: no method that writes or deletes");
  is("GET is the only handler", Object.keys(route).filter((name) => /^(GET|HEAD|POST|PUT|PATCH|DELETE|OPTIONS)$/.test(name)).sort(), ["GET"]);

  part("a page of 1,000 entries: exactly one token call, get-only, for '*'");
  reset();
  const before = Date.now();
  blobWorld.pages = [listing(blobs(0, 1000))];
  answer = await call(`?source=blob&store=${STORE}`);
  const full = parseFilesPage(answer.json) as BackupFilesPage;
  is("answered 200, complete, 1,000 entries", [answer.status, full.complete, full.reason, full.cursor, full.entries.length], [200, true, "done", null, 1000]);
  is("one listing call, of the store's folder, 1,000 at most", blobWorld.listCalls.map((c) => [c.prefix, c.limit, c.cursor]), [[PREFIX, 1000, undefined]]);
  is("exactly ONE token call", blobWorld.tokenCalls.length, 1);
  const token = blobWorld.tokenCalls[0];
  const until = Number(token.validUntil);
  is("get only, every pathname, 15 minutes at most", [token.operations, token.pathname, until > before, until <= Date.now() + BACKUP_FILES_URL_SECONDS * 1000], [["get"], "*", true, true]);
  is("one local signature per entry, each a private get", [blobWorld.presignCalls.length, blobWorld.presignCalls.every((c) => (c.options as Record<string, unknown>).operation === "get" && (c.options as Record<string, unknown>).access === "private")], [1000, true]);
  is("each entry is the listed object, its etag and size, and its signed URL", full.entries[7], { source: "blob", key: `${PREFIX}file-00007.pdf`, etag: '"e7"', size: 107, url: full.entries[7].url, expiresAt: full.entries[7].expiresAt });
  is("each URL expires when the token does, or sooner", full.entries.every((e) => e.expiresAt <= until && e.url.startsWith("https://")), true);
  is("no clientSigningToken, Blob write token or route secret in the answer", [answer.text.includes("client-signing-secret-synthetic"), answer.text.includes("vercel_blob_rw_"), answer.text.includes(SECRET)], [false, false, false]);
  is("the database: the day's count only (SET NX EX, INCRBY)", commands.map((c) => c[0]), ["SET", "INCRBY"]);

  part("an empty folder: no token call, complete only because the listing said so");
  reset();
  blobWorld.pages = [listing([])];
  answer = await call(`?source=blob&store=${STORE}`);
  is("complete, empty, no token", [answer.status, (answer.json as BackupFilesPage).complete, (answer.json as BackupFilesPage).entries.length, blobWorld.tokenCalls.length], [200, true, 0, 0]);

  part("an unreadable or malformed listing is a 503, never an empty, complete page (rule 24)");
  const broken: [string, () => void][] = [
    ["the store cannot be reached", () => { blobWorld.listFails = true; }],
    ["no answer", () => { blobWorld.pages = [null]; }],
    ["blobs not a list", () => { blobWorld.pages = [{ blobs: {}, hasMore: false }]; }],
    ["hasMore missing", () => { blobWorld.pages = [{ blobs: blobs(0, 2) }]; }],
    ["hasMore true without a cursor", () => { blobWorld.pages = [{ blobs: blobs(0, 2), hasMore: true }]; }],
    ["more than 1,000 entries", () => { blobWorld.pages = [listing(blobs(0, 1001))]; }],
    ["an entry without its etag", () => { blobWorld.pages = [listing([{ pathname: `${PREFIX}a`, size: 1 }])]; }],
    ["an entry outside the store's folder", () => { blobWorld.pages = [listing(blobs(0, 1, () => `stores/${OTHER}/a`))]; }],
    ["a size that is not a count", () => { blobWorld.pages = [listing([{ pathname: `${PREFIX}a`, size: "1", etag: "e" }])]; }],
    ["the same object twice", () => { blobWorld.pages = [listing([...blobs(0, 1), ...blobs(0, 1)])]; }],
    ["the token cannot be issued", () => { blobWorld.pages = [listing(blobs(0, 2))]; blobWorld.tokenFails = true; }],
    ["a token without its signing key", () => { blobWorld.pages = [listing(blobs(0, 2))]; blobWorld.token = { delegationToken: "d", validUntil: Date.now() + 600_000 }; }],
    ["a token that has run out", () => { blobWorld.pages = [listing(blobs(0, 2))]; blobWorld.token = { delegationToken: "d", clientSigningToken: "c", validUntil: Date.now() - 1 }; }],
  ];
  for (const [what, arrange] of broken) {
    reset();
    arrange();
    const got = await call(`?source=blob&store=${STORE}`);
    is(`${what}: 503 with no entries`, [got.status, got.text.includes("entries")], [503, false]);
  }

  part("pages: a cursor to go on from, and a store over its pages is never complete");
  reset();
  blobWorld.pages = [listing(blobs(0, 1000), "p1")];
  const first = (await call(`?source=blob&store=${STORE}`)).json as BackupFilesPage;
  is("first page: incomplete, more, with a cursor", [first.complete, first.reason, typeof first.cursor], [false, "more", "string"]);
  blobWorld.pages = [listing(blobs(1000, 5))];
  const second = (await call(`?source=blob&store=${STORE}&cursor=${first.cursor}`)).json as BackupFilesPage;
  is("the cursor asks the provider for its own next page", blobWorld.listCalls[1].cursor, "p1");
  is("second page: the rest, complete", [second.complete, second.entries.length, second.entries[0].key], [true, 5, `${PREFIX}file-01000.pdf`]);
  reset();
  let cursor: string | null = null;
  let last: BackupFilesPage | null = null;
  for (let n = 0; n < BACKUP_FILES_PAGES_PER_STORE; n += 1) {
    blobWorld.pages = [listing(blobs(n * 1000, 1000), `p${n + 1}`)];
    last = (await call(`?source=blob&store=${STORE}${cursor ? `&cursor=${cursor}` : ""}`)).json as BackupFilesPage;
    cursor = last.cursor;
  }
  is("the 10th page with more behind it: over_bound, incomplete, no cursor", [last?.complete, last?.reason, last?.cursor, last?.entries.length], [false, "over_bound", null, 1000]);

  part("the internal cutoff: an incomplete page with a cursor, and a resume that loses and repeats nothing");
  reset();
  let clock = 0;
  blobWorld.pages = [listing(blobs(0, 10))];
  const cut = await backupFilesPage({ source: "blob", store: STORE, cursor: null }, { stopAt: 1_000, now: () => (clock += 150) });
  is("stopped while signing: incomplete, cutoff, with a cursor", [cut.complete, cut.reason, typeof cut.cursor, cut.entries.length > 0 && cut.entries.length < 10], [false, "cutoff", "string", true]);
  blobWorld.pages = [listing(blobs(0, 10))];
  const rest = await backupFilesPage({ source: "blob", store: STORE, cursor: cut.cursor }, { stopAt: Number.POSITIVE_INFINITY });
  const keys = [...cut.entries, ...rest.entries].map((e) => e.key);
  is("together, every entry once", [rest.complete, keys.length, new Set(keys).size, keys[0], keys[9]], [true, 10, 10, `${PREFIX}file-00000.pdf`, `${PREFIX}file-00009.pdf`]);
  is("the resume read the same provider page again", blobWorld.listCalls.map((c) => c.cursor), [undefined, undefined]);
  reset();
  clock = 0;
  const late = await backupFilesPage({ source: "blob", store: STORE, cursor: null }, { stopAt: 0, now: () => (clock += 1) });
  is("past the cutoff before listing: nothing asked, incomplete with a cursor", [late.complete, late.reason, late.entries.length, typeof late.cursor, blobWorld.listCalls.length], [false, "cutoff", 0, "string", 0]);
  reset();
  blobWorld.pages = [listing(blobs(0, 1000, (n) => `${PREFIX}${"k".repeat(900)}-${n}`))];
  const heavy = await backupFilesPage({ source: "blob", store: STORE, cursor: null }, { stopAt: Number.POSITIVE_INFINITY });
  is("long names: stopped under 1 MB, incomplete with a cursor", [heavy.complete, heavy.reason, Buffer.byteLength(JSON.stringify(heavy)) <= 1_000_000, heavy.entries.length < 1000], [false, "page_bytes", true, true]);
  is("and the page still parses", parseFilesPage(JSON.stringify(heavy)).reason, "page_bytes");

  part("the day's reviewed pages: counted before the provider, and refused past them");
  reset();
  for (let n = 0; n < 40; n += 1) await redis.pipeline([["INCRBY", `nl:backup:files:day:${new Date().toISOString().slice(0, 10)}:blob`, 1]]);
  commands = [];
  blobWorld.pages = [listing(blobs(0, 2))];
  answer = await call(`?source=blob&store=${STORE}`);
  is("past the review's 40 a day: 429, nothing listed", [answer.status, blobWorld.listCalls.length], [429, 0]);
  reset();
  redis.pipeline = (async (list: unknown[][]) => { commands.push(...list); return ["OK", "1"]; }) as typeof redis.pipeline;
  blobWorld.pages = [listing(blobs(0, 2))];
  answer = await call(`?source=blob&store=${STORE}`);
  is("a count that does not read as a whole number: 503, nothing listed", [answer.status, blobWorld.listCalls.length], [503, 0]);
  redis.pipeline = (async () => { throw new Error("TEST: the database is down"); }) as typeof redis.pipeline;
  answer = await call(`?source=blob&store=${STORE}`);
  is("a database that cannot be reached: 503, nothing listed", [answer.status, blobWorld.listCalls.length], [503, 0]);
  redis.pipeline = (async (list: unknown[][]) => { commands.push(...list); return realPipeline(list as (string | number)[][]); }) as typeof redis.pipeline;

  part("sources whose provider details are unconfirmed stay off; deletion records are not kept yet");
  reset();
  for (const source of ["r2", "bunny"]) {
    answer = await call(`?source=${source}&store=${STORE}`);
    is(`${source}: 503 source_off, nothing listed or counted`, [answer.status, (answer.json as { error?: string }).error, blobWorld.listCalls.length, commands.length], [503, "source_off", 0, 0]);
  }
  answer = await call("?page=deletions");
  is("deletion records: 503, never an empty, complete page", [answer.status, (answer.json as { error?: string }).error, answer.text.includes("records")], [503, "deletions_unavailable", false]);

  part("a request it does not understand is refused before any work");
  reset();
  const forged = Buffer.from(JSON.stringify({ v: 1, s: "blob", st: OTHER, p: 1, c: "p1", a: null })).toString("base64url");
  for (const [what, query] of [
    ["no source", `?store=${STORE}`],
    ["an unknown source", `?source=s3&store=${STORE}`],
    ["a store that is not a folder", "?source=blob&store=../x"],
    ["an unknown parameter", `?source=blob&store=${STORE}&delete=1`],
    ["a cursor that is not one", `?source=blob&store=${STORE}&cursor=%7B%7D`],
    ["a cursor of another store", `?source=blob&store=${STORE}&cursor=${forged}`],
    ["a cursor past the store's pages", `?source=blob&store=${STORE}&cursor=${Buffer.from(JSON.stringify({ v: 1, s: "blob", st: STORE, p: 10, c: "p", a: null })).toString("base64url")}`],
  ] as const) {
    is(`${what}: 400`, (await call(query)).status, 400);
  }
  is("nothing listed or counted for any of them", [blobWorld.listCalls.length, commands.length], [0, 0]);
  is("a good cursor reads back as itself", decodeFilesCursor(Buffer.from(JSON.stringify({ v: 1, s: "blob", st: STORE, p: 2, c: "p2", a: null })).toString("base64url"), "blob", STORE), { page: 2, provider: "p2", after: null });
  done();
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

tests/backup-files-contract.test.ts:
/**
 * 273 [BK1], files part 1: the exact JSON the backup Worker reads from the
 * site's listing route (lib/backup-files-contract.ts), and the strict parsers
 * the Worker reuses. Synthetic pages only.
 *
 * What fails here (rule 24: unknown is never success, zero or absent):
 *   - any unknown shape read as a page: an extra or a missing field, a wrong
 *     type, an entry of another source or outside the store's folder, a
 *     duplicate key, a size that is not a whole count, a plain-http URL;
 *   - a page that says it is complete while it carries a cursor, or that is
 *     incomplete with nothing to go on from (other than over_bound);
 *   - more than 1,000 entries or 1 MB in a page;
 *   - a deletion record with a reason or a date the contract does not know,
 *     or deletion records mixed into a files page;
 *   - the bounds of item 8 drifting from the route's own pages.
 */
import {
  BACKUP_FILES_HELD_OBJECTS,
  BACKUP_FILES_OBJECTS_PER_MONTH,
  BACKUP_FILES_PAGE_BYTES,
  BACKUP_FILES_PAGE_ENTRIES,
  BACKUP_FILES_PAGES_PER_STORE,
  BACKUP_FILES_URL_SECONDS,
  BackupFilesContractError,
  parseDeletionPage,
  parseFilesPage,
  sourcePrefix,
} from "@/lib/backup-files-contract";
import { done, is, part } from "./check";

const STORE = "0123456789abcdef0123456789abcdef";
const entry = (n: number, over: Record<string, unknown> = {}) => ({
  source: "blob",
  key: `stores/${STORE}/f${n}.pdf`,
  etag: `"etag${n}"`,
  size: 1000 + n,
  url: `https://store.private.blob.vercel-storage.com/stores/${STORE}/f${n}.pdf?sig=${n}`,
  expiresAt: 1_800_000_000_000,
  ...over,
});
const page = (over: Record<string, unknown> = {}) => ({
  version: 1,
  kind: "files",
  source: "blob",
  store: STORE,
  entries: [entry(1), entry(2)],
  cursor: null,
  complete: true,
  reason: "done",
  ...over,
});
const without = (value: Record<string, unknown>, field: string) => Object.fromEntries(Object.entries(value).filter(([name]) => name !== field));
const refused = (raw: unknown): boolean => {
  try {
    parseFilesPage(raw);
    return false;
  } catch (error) {
    return error instanceof BackupFilesContractError;
  }
};
const recordRefused = (raw: unknown): boolean => {
  try {
    parseDeletionPage(raw);
    return false;
  } catch (error) {
    return error instanceof BackupFilesContractError;
  }
};

part("the bounds of item 8, matched to the route's pages");
is("a page holds at most 1,000 entries and 1 MB", [BACKUP_FILES_PAGE_ENTRIES, BACKUP_FILES_PAGE_BYTES], [1000, 1_000_000]);
is("a complete listing of one source of one store is at most 10 pages", BACKUP_FILES_PAGES_PER_STORE, 10);
is("so a store can hold at most pages × entries objects a source and still list complete", BACKUP_FILES_HELD_OBJECTS, BACKUP_FILES_PAGES_PER_STORE * BACKUP_FILES_PAGE_ENTRIES);
is("the objects copied for one store a month are the 10,000 priced (docs/backup-costs-2026-11-08.md, 5b), never more than one complete listing", [BACKUP_FILES_OBJECTS_PER_MONTH, BACKUP_FILES_OBJECTS_PER_MONTH <= BACKUP_FILES_HELD_OBJECTS], [10_000, true]);
is("a signed URL lasts 15 minutes", BACKUP_FILES_URL_SECONDS, 900);
is("each source's folder", [sourcePrefix("r2", STORE), sourcePrefix("blob", STORE), sourcePrefix("bunny", STORE)], [`vault/${STORE}/`, `stores/${STORE}/`, null]);

part("a good page reads as itself, from an object or from its text");
const good = page();
is("the object", parseFilesPage(good), good);
is("the text", parseFilesPage(JSON.stringify(good)), good);
is("an incomplete page with a cursor", parseFilesPage(page({ complete: false, reason: "more", cursor: "abc_DEF-1" })).cursor, "abc_DEF-1");
is("a page cut off with nothing signed yet is incomplete, never empty-and-complete", parseFilesPage(page({ entries: [], complete: false, reason: "cutoff", cursor: "x" })).complete, false);
is("over the bound: incomplete for good, no cursor", parseFilesPage(page({ complete: false, reason: "over_bound", cursor: null })).reason, "over_bound");
is("an empty, complete listing of a folder that is confirmed empty", parseFilesPage(page({ entries: [] })).entries.length, 0);

part("every unknown shape throws");
is("not an object", [refused(null), refused([]), refused("not json"), refused(7)], [true, true, true, true]);
is("an extra field", refused({ ...good, note: "x" }), true);
is("a missing field", refused(without(good, "reason")), true);
is("another version or kind", [refused(page({ version: 2 })), refused(page({ kind: "deletions" }))], [true, true]);
is("an unknown source, or bunny (not built)", [refused(page({ source: "s3" })), refused(page({ source: "bunny", entries: [] }))], [true, true]);
is("a store that is not a folder", refused(page({ store: "../x" })), true);
is("complete with a cursor", refused(page({ cursor: "x" })), true);
is("complete with another reason", refused(page({ reason: "more" })), true);
is("incomplete with nothing to go on from", refused(page({ complete: false, reason: "more", cursor: null })), true);
is("incomplete and called done", refused(page({ complete: false, reason: "done", cursor: "x" })), true);
is("over_bound with a cursor", refused(page({ complete: false, reason: "over_bound", cursor: "x" })), true);
is("an unknown reason", refused(page({ complete: false, reason: "partial", cursor: "x" })), true);
is("a cursor with characters outside base64url", refused(page({ complete: false, reason: "more", cursor: "a b" })), true);
is("a complete flag that is not a boolean", refused(page({ complete: "true" })), true);
is("entries that are not a list", refused(page({ entries: {} })), true);
is("more than 1,000 entries", refused(page({ entries: Array.from({ length: 1001 }, (_, i) => entry(i)) })), true);
is("more than 1 MB", refused(page({ entries: [entry(1, { key: `stores/${STORE}/${"a".repeat(1000)}`, url: `https://x.example/${"b".repeat(1_000_000)}` })] })), true);

part("every unknown entry throws");
is("an extra or a missing field", [refused(page({ entries: [{ ...entry(1), mode: "x" }] })), refused(page({ entries: [without(entry(1), "etag")] }))], [true, true]);
is("an entry of another source", refused(page({ entries: [entry(1, { source: "r2" })] })), true);
is("a key outside the store's folder", refused(page({ entries: [entry(1, { key: "stores/ffffffffffffffffffffffffffffffff/a.pdf" })] })), true);
is("a key with a control character, or empty after the folder", [refused(page({ entries: [entry(1, { key: `stores/${STORE}/a\nb` })] })), refused(page({ entries: [entry(1, { key: `stores/${STORE}/` })] }))], [true, true]);
is("the same key twice", refused(page({ entries: [entry(1), entry(1)] })), true);
is("an empty or spaced etag", [refused(page({ entries: [entry(1, { etag: "" })] })), refused(page({ entries: [entry(1, { etag: "a b" })] }))], [true, true]);
is("a size that is negative, fractional, a string or unsafe", [-1, 1.5, "10", 2 ** 53].map((size) => refused(page({ entries: [entry(1, { size })] }))), [true, true, true, true]);
is("a plain-http, credentialed or unparsable URL", ["http://x.example/a", "https://u:p@x.example/a", "not a url"].map((url) => refused(page({ entries: [entry(1, { url })] }))), [true, true, true]);
is("an expiry that is not a positive whole time", [0, -5, 1.5, "1"].map((expiresAt) => refused(page({ entries: [entry(1, { expiresAt })] }))), [true, true, true, true]);

part("deletion records, on their own page");
const record = { source: "r2", key: `vault/${STORE}/owner/abc/f.pdf`, recordedAt: 1_800_000_000_000, reason: "creator_deleted" };
const deletions = { version: 1, kind: "deletions", records: [record], cursor: null, complete: true, reason: "done" };
is("a good page of records", parseDeletionPage(deletions), deletions);
is("every reason the contract knows", ["creator_deleted", "store_closed", "privacy_request"].map((reason) => recordRefused({ ...deletions, records: [{ ...record, reason }] })), [false, false, false]);
is("an unknown reason, date or extra field", [recordRefused({ ...deletions, records: [{ ...record, reason: "other" }] }), recordRefused({ ...deletions, records: [{ ...record, recordedAt: "2026-11-08" }] }), recordRefused({ ...deletions, records: [{ ...record, person: "a@b.c" }] })], [true, true, true]);
is("a files page is never read as records, nor records as files", [recordRefused(good), refused(deletions)], [true, true]);
is("complete with a cursor, or incomplete without", [recordRefused({ ...deletions, cursor: "x" }), recordRefused({ ...deletions, complete: false, reason: "more" })], [true, true]);

done();

tests/backup-files-off.test.ts:
/**
 * 273 [BK1], files part 1: the backup files route stays off on main. With
 * the real BACKUP_FILES_ROUTE_REVIEW (null until the owner approves the
 * cost), a call carrying the route's own secret is still a 404, and nothing
 * is listed, signed or counted. Only the owner records that review.
 */
import { GET } from "@/app/api/backup/files/route";
import { BACKUP_FILES_ROUTE_REVIEW } from "@/lib/backup-files-review";
import { blobWorld, resetBlobWorld } from "./backup-files-world";
import { store as redis } from "./redis-stub";
import { done, is, part } from "./check";

const STORE = "0123456789abcdef0123456789abcdef";
const SECRET = "route-secret-synthetic-0123456789abcdef";
let commands = 0;
const real = redis.pipeline;
redis.pipeline = (async (list: (string | number)[][]) => { commands += list.length; return real(list); }) as typeof redis.pipeline;

async function main(): Promise<void> {
  part("no review of the route's cost: off, even with its secret");
  resetBlobWorld();
  blobWorld.pages = [{ blobs: [], hasMore: false }];
  process.env.BACKUP_FILES_ROUTE_SECRET = SECRET;
  is("the review is null on main", BACKUP_FILES_ROUTE_REVIEW, null);
  const response = await GET(new Request(`https://marktmorgen.test/api/backup/files?source=blob&store=${STORE}`, { headers: { authorization: `Bearer ${SECRET}` } }));
  is("404", response.status, 404);
  is("nothing listed, signed or counted", [blobWorld.listCalls.length, blobWorld.tokenCalls.length, commands], [0, 0, 0]);
  done();
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

